      "accuracy": {
        "verdict": "accurate",
        "reason": "Strontium salts (such as strontium carbonate or nitrate) are standard pyrotechnic colorants used to produce brilliant red fireworks.",
        "errors": []
      }
    },
    {
      "id": "u18",
      "kind": "EXAMPLE",
      "label": "Applications of barium in medical imaging and fireworks",
      "excerpts": [
        {
          "text": "- **Barium** compounds are used in some medical imaging procedures and fireworks.",
          "occurrence": 0
        }
      ],
      "attributes": {
        "context": "real_world",
        "treatment": "illustrative"
      },
      "contextualization": {
        "value": "none",
        "evidence": []
