      "accuracy": {
        "verdict": "accurate",
        "reason": "Barium sulfate is widely used as a radio-contrast agent for gastrointestinal X-ray imaging ('barium meal'), and barium compounds are used to produce green colors in pyrotechnics.",
        "errors": []
      }
    },
    {
      "id": "u19",
      "kind": "EXAMPLE",
      "label": "Application of beryllium in lightweight aerospace and electronic alloys",
      "excerpts": [
        {
          "text": "- **Beryllium** is used in lightweight, strong materials for aircraft and electronics.",
          "occurrence": 0
        }
      ],
      "attributes": {
        "context": "real_world",
        "treatment": "illustrative"
      },
      "contextualization": {
        "value": "none",
        "evidence": []
